#nullable enable // autogenerated

using MVZ2Logic;
using MVZ2Logic.Commands;
using MVZ2Logic.Definitions;
using MVZ2Logic.Level;
using MVZ2Logic.Saves;

namespace MVZ2.GameContent.Commands
{
    [AutoCommandDefinition(VanillaCommandNames.money)]
    public class Money : CommandDefinition
    {
        public Money(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Invoke(string[] parameters)
        {
            var game = Global.Game;
            var mode = parameters[0];
            var amount = ParseHelper.ParseInt(parameters[1]);
            if (mode == "set")
            {
                Global.Saves.SetMoney(amount);
            }
            else if (mode == "add")
            {
                Global.Saves.AddMoney(amount);
            }
        }
    }
}